def build(template):
    html = template.replace("__DATA__", json.dumps(DATA, ensure_ascii=False))
    html = html.replace("ranker-choice-form-2026-11-16", "ranker-holdout-form-2026-11-16").replace("ranker-choice-2026-11-16", "ranker-holdout-2026-11-16")
    html = html.replace("RANKER_CHOICES", "RANKER_HOLDOUT").replace("ranker_choice_answers.json", "ranker_holdout_answers.json")
    html = html.replace("<title>ฟอร์มเลือกประโยค 30 สถานการณ์</title>", "<title>ฟอร์มชุดตัดสิน 30 สถานการณ์</title>")
    html = html.replace("<h1>เลือกประโยคที่ฟังเป็นคุณ: 30 สถานการณ์</h1>", "<h1>ชุดตัดสิน: เลือกประโยคที่ฟังเป็นคุณ (30 สถานการณ์ใหม่)</h1>")
    html = html.replace("<details open><summary>อ่านก่อนเริ่ม (2 นาที)</summary>",
                        '<details open><summary>ชุดนี้ต่างจากชุดแรกอย่างไร (อ่านก่อน)</summary><p><b>ชุดแรกใช้พัฒนากฎใหม่ไปแล้ว ผมเห็นผลของมันแล้ว ชุดนี้เป็นสถานการณ์ใหม่และประโยคใหม่ทั้งหมด ใช้ตัดสินว่ากฎใหม่ใช้ได้จริงไหม</b> จึงสำคัญที่คุณติ๊กตามที่คุณจะพูดจริง ไม่ต้องติ๊กทุกข้อถ้าบางประโยคฟังไม่เหมือนคุณ ผมไม่เห็นผลของกฎกับชุดนี้ก่อนคุณตอบ และกฎถูกตรึงไว้แล้ว</p></details>\n<details open><summary>อ่านก่อนเริ่ม (2 นาที)</summary>')
    return html


